class Solution {
        public int minOperations(String s) {
                int n = s.length();
                        
                                // 1. Check if already sorted
                                        boolean sorted = true;
                                                for (int i = 0; i < n - 1; i++) {
                                                            if (s.charAt(i) > s.charAt(i + 1)) {
                                                                            sorted = false;
                                                                                            break;
                                                                                                        }
                                                                                                                }
                                                                                                                        if (sorted) return 0;
                                                                                                                                
                                                                                                                                        // 2. If length is 2 and not sorted, it's impossible
                                                                                                                                                if (n == 2) return -1;
                                                                                                                                                        
                                                                                                                                                                char minChar = s.charAt(0);
                                                                                                                                                                        char maxChar = s.charAt(0);
                                                                                                                                                                                for (int i = 0; i < n; i++) {
                                                                                                                                                                                            char c = s.charAt(i);
                                                                                                                                                                                                        if (c < minChar) minChar = c;
                                                                                                                                                                                                                    if (c > maxChar) maxChar = c;
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                            // 3. Check if min character is at the start or max character is at the end
                                                                                                                                                                                                                                                    if (s.charAt(0) == minChar || s.charAt(n - 1) == maxChar) {
                                                                                                                                                                                                                                                                return 1;
                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                        // 4. Check condition for 3 operations (unique max at start and unique min at end)
                                                                                                                                                                                                                                                                                                if (s.charAt(0) == maxChar && s.charAt(n - 1) == minChar) {
                                                                                                                                                                                                                                                                                                            boolean uniqueMaxStart = true;
                                                                                                                                                                                                                                                                                                                        boolean uniqueMinEnd = true;
                                                                                                                                                                                                                                                                                                                                    for (int i = 1; i < n; i++) {
                                                                                                                                                                                                                                                                                                                                                    if (s.charAt(i) == maxChar) uniqueMaxStart = false;
                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                            for (int i = 0; i < n - 1; i++) {
                                                                                                                                                                                                                                                                                                                                                                                            if (s.charAt(i) == minChar) uniqueMinEnd = false;
                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                    if (uniqueMaxStart && uniqueMinEnd) {
                                                                                                                                                                                                                                                                                                                                                                                                                                    return 3;
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 5. Fallback to 2 operations for other general cases
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
